			m_Finished = true;
			StopSDTimers();
			ArrayList remaining = new ArrayList();
			for ( int i = 0; i < m_Participants.Count; ++i )
			{
				Participant p = (Participant)m_Participants[i];
				if ( p.Eliminated )
				{
