			exposed_nodes, order, M, supernodes, B, b = self.add_b_to_branching(exposed_nodes, order, M, supernodes, B)
			if b is None:
				continue
			b_u, b_v, b_key, b_data = b
			origin_u, origin_v = b_data['origin'][:2]
